```json
{
  "modules": [
    {
      "id": "outcome_gated_wm_reliance",
      "name": "Outcome-Gated WM Reliance",
      "description": "A latent gate tracks recent reward history with asymmetric win/loss sensitivities and modulates the baseline WM weight via a logistic transform.",
      "params": [
        {
          "name": "outcome_gated_wm_reliance_win_boost",
          "bounds": [
            0,
            10
          ]
        },
        {
          "name": "outcome_gated_wm_reliance_loss_suppression",
          "bounds": [
            0,
            10
          ]
        },
        {
          "name": "outcome_gated_wm_reliance_kappa",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "slots": {
        "init": "outcome_gated_wm_reliance_g = 0.0",
        "block_init": "outcome_gated_wm_reliance_g = 0.0",
        "pre_choice": "outcome_gated_wm_reliance_g = (1.0 - outcome_gated_wm_reliance_kappa) * outcome_gated_wm_reliance_g + outcome_gated_wm_reliance_kappa * (outcome_gated_wm_reliance_win_boost if r > 0.5 else -outcome_gated_wm_reliance_loss_suppression)"
      },
      "overrides": {
        "mix_weight": "1.0 / (1.0 + np.exp(-(np.log(np.clip(wm_weight, 1e-12, 1.0 - 1e-12) / (1.0 - np.clip(wm_weight, 1e-12, 1.0 - 1e-12))) + outcome_gated_wm_reliance_g)))"
      },
      "provenance": [
        3
      ],
      "excludes": [
        "load_scaled_wm_weight",
        "load_dependent_wm_arbitration"
      ]
    }
  ]
}
```
